+    fn dictionary_inputs_preserve_nulls_and_slices() {
+        use arrow::array::{BooleanArray, DictionaryArray};
+        use arrow::compute::cast;
+
+        let values =
+            VariantArray::from_iter([Some(Variant::Int32(123)), None, Some(Variant::Int32(-45))]);
